using System.Text;
using System.Text.RegularExpressions;
using CareerOS.Domain.Common;
using Microsoft.Extensions.Configuration;

namespace CareerOS.Infrastructure.Documents;

// Keys are generated by the server; user filenames never participate in a path.
public sealed class LocalDocumentStore
{
    public const int MaxBytes = 5 * 1024 * 1024;
    private readonly string root;
    public LocalDocumentStore(IConfiguration config, string? contentRoot = null)
    {
        var configured = config["Documents:StorageRoot"] ?? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "CareerOS", "documents");
        if (!Path.IsPathFullyQualified(configured)) throw new InvalidOperationException("Document storage requires an absolute path.");
        root = Path.GetFullPath(configured);
        foreach (var forbidden in new[] { contentRoot, AppContext.BaseDirectory, Directory.GetCurrentDirectory() }.Where(x => x != null))
        {
            var relative = Path.GetRelativePath(Path.GetFullPath(forbidden!), root);
            if (relative == "." || (!Path.IsPathRooted(relative) && relative != ".." && !relative.StartsWith(".." + Path.DirectorySeparatorChar)))
                throw new InvalidOperationException("Document storage must be outside the application directory.");
        }
        for (var p = new DirectoryInfo(root); p != null; p = p.Parent)
        {
            if (Directory.Exists(Path.Combine(p.FullName, ".git")) || File.Exists(Path.Combine(p.FullName, ".git")))
                throw new InvalidOperationException("Document storage must be outside a Git checkout.");
        }
        Directory.CreateDirectory(root);
        CheckLinks(root);
        if (!OperatingSystem.IsWindows()) File.SetUnixFileMode(root, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
    }
    private static void CheckLinks(string path)
    {
        for (var p = new DirectoryInfo(path); p != null; p = p.Parent)
            if ((p.Attributes & FileAttributes.ReparsePoint) != 0) throw new IOException("Linked storage directories are forbidden.");
    }
    public string PathFor(string key)
    {
        if (!Regex.IsMatch(key, "\\A[a-f0-9]{32}\\.pdf\\z")) throw new FileNotFoundException();
        CheckLinks(root);
        var path = Path.Combine(root, key);
        if (File.Exists(path) && (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0) throw new IOException("Linked files are forbidden.");
        return path;
    }
    public static string SafeName(string name)
    {
        name = name.Replace('\\', '/').Split('/').Last();
        name = Regex.Replace(name, "[^a-zA-Z0-9._ -]", "_").Trim(' ', '.');
        if (name.Length > 120) name = name[..120];
        if (!name.EndsWith(".pdf", StringComparison.OrdinalIgnoreCase)) throw new DomainValidationException("Choose a .pdf file.");
        if (Regex.IsMatch(name, "^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])\\.", RegexOptions.IgnoreCase)) name = "_" + name;
        return name;
    }
    public static async Task<byte[]> Validate(Stream input, string mime, CancellationToken ct)
    {
        if (!string.Equals(mime, "application/pdf", StringComparison.OrdinalIgnoreCase)) throw new DomainValidationException("Only PDF files (application/pdf) are supported.");
        using var buffer = new MemoryStream();
        var chunk = new byte[81920]; int n;
        while ((n = await input.ReadAsync(chunk, ct)) > 0)
        {
            if (buffer.Length + n > MaxBytes) throw new DocumentTooLargeException();
            buffer.Write(chunk, 0, n);
        }
        var bytes = buffer.ToArray();
        if (bytes.Length < 16 || !bytes.AsSpan(0, 5).SequenceEqual("%PDF-"u8) ||
            !Encoding.ASCII.GetString(bytes, Math.Max(0, bytes.Length - 1024), Math.Min(1024, bytes.Length)).TrimEnd().EndsWith("%%EOF", StringComparison.Ordinal))
            throw new DomainValidationException("The file does not have a valid PDF signature and end marker.");
        return bytes;
    }
    public async Task<string> Write(byte[] bytes, CancellationToken ct)
    {
        var key = Guid.NewGuid().ToString("N") + ".pdf";
        var path = PathFor(key);
        try
        {
            await using var file = new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None);
            if (!OperatingSystem.IsWindows()) File.SetUnixFileMode(path, UnixFileMode.UserRead | UnixFileMode.UserWrite);
            await file.WriteAsync(bytes, ct); await file.FlushAsync(ct);
            file.Flush(true);
            return key;
        }
        catch { File.Delete(path); throw; }
    }
    public Stream Open(string key) => new FileStream(PathFor(key), FileMode.Open, FileAccess.Read, FileShare.Read | FileShare.Delete);
    public void Delete(string key) => File.Delete(PathFor(key));
}
public sealed class DocumentTooLargeException : Exception;
public sealed class DocumentMissingException : Exception;
public sealed class DocumentConflictException(string message) : Exception(message);
